function startPen() {
	for (let px = -320; px < -237.5; px += 9) {
		pts.push({
			x: px,
			y: map(px, -320, -237.5, 320, 487.5),
			pen: false
		});
	}
}

function parkPen() {
	for (let px = x; px >= -320; px -= 10) {
		pts.push({
			x: px,
			y: map(px, 0, -320, 250, 320),
			pen: false
		});
	}
}

function addCircles(cx, cy) {
	for (let r = 75; r >= 5; r -= 10) {
		pts.push({
			x: cx + 75 + r,
			y: cy - r,
			pen: false
		});
		for (let i = 0; i <= 24; i++) {
			let a = i * TAU / 24;
			pts.push({
				x: cx + 75 + r * cos(a),
				y: cy - r + r * sin(a),
				pen: true
			});
		}
	}
}

function addWaves(cx, cy) {
	let wa = PI;
	for (let wy = 10; wy < 150; wy += 14) {
		pts.push({
			x: cx,
			y: cy - wy + sin(wa) * 6,
			pen: false
		});
		for (let wx = 0; wx <= 150; wx += 7.5) {
			pts.push({
				x: cx + wx,
				y: cy - wy + sin(wa) * 6,
				pen: true
			});
			wa += PI / 6;
		}
	}
}

function makeSquare(cx, cy) {
	pts.push({
		x: cx,
		y: cy,
		pen: false
	});
	for (let x = cx; x < cx + 150; x += 25) {
		pts.push({
			x: x,
			y: cy,
			pen: true
		});
	}
	for (let y = cy; y > cy - 150; y -= 25) {
		pts.push({
			x: cx + 150,
			y: y,
			pen: true
		});
	}
	for (let x = cx + 150; x > cx; x -= 25) {
		pts.push({
			x: x,
			y: cy - 150,
			pen: true
		});
	}
	for (let y = cy - 150; y <= cy; y += 25) {
		pts.push({
			x: cx,
			y: y,
			pen: true
		});
	}
}

function addSunburst(cx, cy) {
	for (let i = 0; i < 24; i++) {
		let a = i * TAU / 24;
		pts.push({
			x: cx + 75,
			y: cy - 75,
			pen: false
		});
		for (let r = 10; r <= 120; r += 5) {
			if (abs(r * cos(a)) > 76 || abs(r * sin(a)) > 76) continue;
			pts.push({
				x: cx + 75 + r * cos(a),
				y: cy - 75 + r * sin(a),
				pen: true
			});
		}
	}
}

function addScales(cx, cy) {
	for (let y = cy; y > cy - 150; y -= 25) {
		for (let x = cx; x < cx + 150; x += 25) {
			pts.push({
				x: x,
				y: y,
