function shadeCircles(cx, cy, sx, sy, sa) {
	for (let i = 0; i <= 24; i++) {
		let a = sa + i * HALF_PI / 24;
		pts.push({
			x: cx + sx,
			y: cy + sy,
			pen: false
		});
		for (let r = 10; r <= 60; r += 4) {
			let rx = cx + sx + r * cos(a);
			let ry = cy + sy - r * sin(a);
			let d = dist(rx, ry, cx + 75, cy - 75)
			if (d < 74) continue;
			pts.push({
				x: rx,
				y: ry,
				pen: true
			});
		}
	}
}

