function shadeScales(cx, cy) {
	for (let row = 0; row < 6; row++) {
		let y = cy - row * 25;
		for (let col = 0; col < 7; col++) {
			if (row % 2 == col % 2) continue;
			let x = cx + col * 25;
			pts.push({
				x: x,
				y: y,
				pen: false
			});
			for (let a = 0; a <= HALF_PI; a += HALF_PI / 15) {
				pts.push({
					x: ((col == 0 || col == 6) ? x : x - 25 + 25 * cos(-a)),
					y: y + 25 * sin(-a),
					pen: false
				});
				pts.push({
					x: ((col == 0 || col == 6) ? x : x - 25 + 25 * cos(-a)),
					y: y + 25 * sin(-a),
					pen: true
				});
				pts.push({
					x: (col == 6 ? (x - 25 + 25 * cos(-a)) : (x + 25 * cos(-a))),
					y: y + 25 * sin(-a),
					pen: true
				});
			}
		}
	}
}

function shadeHerringbone(cx, cy) {
	for (let j = 1; j < 10; j += 1) {
		if (j % 2 == 0) continue;
		let dx = 15 * j;
		for (let sx = 0; sx < 15; sx += 2) {
			pts.push({
				x: cx + dx + sx,
				y: cy,
				pen: false
			});
			let dy = 0;
			for (let i = 10; i > j; i--) {
				dy += 15;
				pts.push({
					x: cx + dx + sx,
					y: cy - dy,
					pen: true
				});
			}
		}
	}

	for (let j = 0; j < 10; j += 1) {
		if (j % 2 == 0) continue;
		let dy = 150 - 15 * j;
		for (let sy = 0; sy < 15; sy += 2) {
			pts.push({
				x: cx + 150,
				y: cy - dy - sy,
				pen: false
			});
			let dx = 0;
			for (let i = 11; i > j; i--) {
				dx += 15;
				pts.push({
					x: cx + 150 - dx,
					y: cy - dy - sy,
					pen: true
				});
			}
		}
	}
}

function shadeSunburst(cx, cy) {
	for (let i = 0; i < 24; i++) {
		let a = i * TAU / 24;
		for (let ring = 0; ring < 6; ring += 1) {
			if (i % 2 == ring % 2) continue;
			let r = 20 + ring * 10;
			pts.push({
				x: cx + 75 + r * cos(a),
				y: cy - 75 + r * sin(a),
				pen: false
			});
			for (let a1 = 0; a1 <= TAU / 24; a1 += TAU / 144) {
				pts.push({
					x: cx + 75 + r * cos(a + a1),
					y: cy - 75 + r * sin(a + a1),
					pen: true
				});
				pts.push({
					x: cx + 75 + (r - 10) * cos(a + a1),
					y: cy - 75 + (r - 10) * sin(a + a1),
					pen: true
				});
			}
		}
	}
}

