// For the #WCCChallenge, theme: "zentangle"
// The pen plotter returns this week! 
// Originally inspired by this presentation on the world's cheapest pen plotter:
// https://youtu.be/u4Jh1daCl60?si=hEjbvhDcXPQrvCKX
// Built with approximately $20 of parts (including a clothespin!), 
// the real-life version produces remarkably good results!

let innerArm, outerArm;
let a1, a2, ta1, ta2;
let x = 0;
let y = 0;
let pen = false;
let pts = [];
let count = 0;
let ease;
let t = 0;

function setup() {
	createCanvas(windowWidth, windowHeight);
	drawing = createGraphics(500, 500);
	innerArm = 320;
	outerArm = 320;
	a1 = -HALF_PI;
	a2 = PI;
	ta1 = -HALF_PI;
	ta2 = HALF_PI;
	makePoints();
	drawPaper();
	readout = createP();
	readout.position(10, 0);
	readout.style('color', 'rgba(0,0,0,0.9)');
	readout.style('font-family', 'monospace');
	slider = createSlider(1, 100, 10, 1);
	slider.position(5, 120);
	ease = new p5.Ease();
}

function draw() {
	imageMode(CENTER);
	for (let i = 0; i < slider.value(); i++) {
		if (frameCount > 90 && t > 0.3) nextPoint();
		moveArms();
		drawPoints();
		updateDisplay();
	}
	push();
	background(220);
	translate(width / 2, height / 2);
	scale(height / 550);
	image(drawing, 0, 0);
	drawArms();
	pop();
}

function nextPoint() {
	x = pts[count].x;
	y = pts[count].y;
	pen = pts[count].pen;
	ta1 = xy_to_angles(x, y).sa;
	ta2 = xy_to_angles(x, y).ea;
	count += 1;
	if (count > pts.length - 1) count = pts.length - 1;
	t = 0;
}

function moveArms() {
	if (pen) t += 0.01;
	else t += 0.01;
	t = constrain(t, 0.0, 1.0);
	let q = ease['generalizedLinearMap'](t);
	a1 = lerp(a1, ta1, q);
	a2 = lerp(a2, ta2, q);
}

function drawPaper() {
	drawing.noFill();
	drawing.stroke(0, 100);
	drawing.background(255);
}

function drawArms() {
	rectMode(CENTER);
	fill(0, 60);
	stroke(255);
	stroke(0);
	strokeWeight(1);
	push();
	translate(0, 250);
	ellipse(0, 0, 5);
	rotate(-HALF_PI);
	rotate(a1);
	translate(innerArm / 2, 0);
	rect(0, 0, innerArm + 20, 20, 10);
	translate(innerArm / 2, 0);
	rotate(a2);
	ellipse(0, 0, 5);
	translate(outerArm / 2, 0);
	rect(0, 0, outerArm + 20, 20, 10);
	translate(outerArm / 2, 0);
	ellipse(0, 0, 5);
	pop();
}

function drawPoints() {
	if (pen == false) return;
	drawing.push();
	drawing.translate(250, 500);
	drawing.rotate(-HALF_PI);
	drawing.rotate(a1);
	drawing.translate(innerArm, 0);
	drawing.rotate(a2);
	drawing.translate(outerArm, 0);
	drawing.fill(0, 0, 0, 150);
	drawing.noStroke();
	drawing.ellipse(0, 0, 2.5);
	drawing.pop();
}

function updateDisplay() {
	let txt = '<u>Doodle Data</u></br>';
	txt += 'point: ' + count + ' of ' + (pts.length - 1) + '</br>';
	txt += 'pen x: ' + prependplus(nf(x, 3, 1)) + ' | pen y: ' + prependplus(nf(y, 3, 1)) + '</br>';
	txt += 'shoulder angle: ' + prependplus(nf(degrees(a1), 3, 1)) + '°</br>';
	txt += 'elbow angle: ' + prependplus(nf(degrees(a2), 3, 1)) + '°</br>';
	let penpos = pen ? 'down' : 'up';
	txt += 'pen tip: ' + penpos + '</br>';
	txt += 'doodle speed: ' + slider.value() + '%</br>';
	if (count == pts.length - 1) {
		txt += 'FINISHED!';
		slider.style('visibility', 'hidden');
	}
	readout.html(txt);
}

// Ported this from Python: https://www.youtube.com/watch?v=u4Jh1daCl60&t=617s
function xy_to_angles(x, y) {
	let hypotenuse = sqrt(x ** 2 + y ** 2);
	if (x == 0 && y == 0) hypotenuse = 0.00001;
	let hypotenuseAngle = asin(x / hypotenuse);
	let innerAngle = acos((hypotenuse ** 2 + innerArm ** 2 - outerArm ** 2) / (2 * hypotenuse * innerArm));
	let outerAngle = acos((innerArm ** 2 + outerArm ** 2 - hypotenuse ** 2) / (2 * innerArm * outerArm));
	shoulderAngle = hypotenuseAngle - innerAngle;
	elbowAngle = PI - outerAngle;
	return {
		sa: shoulderAngle,
		ea: elbowAngle
	};
}

function prependplus(value) {
	if (value >= 0) {
		return "+" + value;
	} else {
		return value.toString();
	}
}

